-- Rebuild Medina Book 4 lesson 10 strictly from the supplied Arabic sharh.
-- Canonical PDF pages: 42-44. DOC text was used only for extraction and checked against the PDF.
begin;

do $migration$
declare
  existing_count integer;
begin
  select count(*) into existing_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '10';
  if existing_count = 2 then
    -- Preserve the legacy ranks row and add four independently headed sharh topics.
    update public.rules set sort_order = 4
    where course_name = 'Мединский курс (Том 4)' and lesson_number = '10' and sort_order = 2;
    insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar) values
      ('Мединский курс (Том 4)', '10', '__book4_lesson10_attached__', '', 2, 'rule', '', null),
      ('Мединский курс (Том 4)', '10', '__book4_lesson10_detached__', '', 3, 'rule', '', null),
      ('Мединский курс (Том 4)', '10', '__book4_lesson10_positions__', '', 5, 'rule', '', null),
      ('Мединский курс (Том 4)', '10', '__book4_lesson10_join__', '', 6, 'rule', '', null);
  elsif existing_count <> 6 then
    raise exception 'Expected 2 legacy or 6 rebuilt Book 4 lesson 10 rules, found %', existing_count;
  end if;
end $migration$;

with incoming(sort_order, title, content, summary, rule_ar) as (
  values
    (1, 'الضَّمَائِرُ وَأَقْسَامُهَا (местоимения и их разряды)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-subject" dir="rtl" lang="ar">الضَّمِيرُ لَفْظٌ يَكْنِي عَنِ الْمُتَكَلِّمِ أَوِ الْمُخَاطَبِ أَوِ الْغَائِبِ نِيَابَةً عَنِ الِاسْمِ، وَفَائِدَتُهُ الِاخْتِصَارُ. وَالضَّمَائِرُ بَارِزَةٌ وَمُسْتَتِرَةٌ، وَالضَّمَائِرُ الْبَارِزَةُ مُتَّصِلَةٌ وَمُنْفَصِلَةٌ.</span><p class="rule-study-text">Местоимение заменяет имя говорящего, собеседника или отсутствующего лица и служит для краткости. Местоимения бывают явно выраженными и скрытыми; явно выраженные делятся на слитные и раздельные.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Основные понятия</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar ar-tone-subject" dir="rtl" lang="ar">الضَّمِيرُ</span><span class="rule-term-ru">местоимение: слово, употреблённое вместо имени</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar ar-tone-subject" dir="rtl" lang="ar">الْمُتَكَلِّمُ</span><span class="rule-term-ru">говорящий</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar ar-tone-subject" dir="rtl" lang="ar">الْمُخَاطَبُ</span><span class="rule-term-ru">тот, к кому обращаются</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar ar-tone-subject" dir="rtl" lang="ar">الْغَائِبُ</span><span class="rule-term-ru">тот, о ком говорят в его отсутствие</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الِاخْتِصَارُ</span><span class="rule-term-ru">краткость — польза местоимения</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Деление местоимений</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْقِسْمُ الْأَوَّلُ</span><span class="rule-table-ru">первый разряд</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْقِسْمُ الثَّانِي</span><span class="rule-table-ru">второй разряд</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">пояснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ضَمَائِرُ بَارِزَةٌ</span><span class="rule-table-ru">явно выраженные местоимения</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ضَمَائِرُ مُسْتَتِرَةٌ</span><span class="rule-table-ru">скрытые местоимения</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْبُرُوزُ وَالِاسْتِتَارُ</span><span class="rule-table-ru">первичное деление: форма выражена либо подразумевается</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ضَمَائِرُ مُتَّصِلَةٌ</span><span class="rule-table-ru">слитные местоимения</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ضَمَائِرُ مُنْفَصِلَةٌ</span><span class="rule-table-ru">раздельные местоимения</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَقْسَامُ الضَّمَائِرِ الْبَارِزَةِ</span><span class="rule-table-ru">два разряда явно выраженных местоимений</span></td></tr></tbody></table></div></div></div>', 'Местоимение заменяет имя говорящего, собеседника или отсутствующего лица и служит для краткости. Местоимения бывают явно выраженными и скрытыми; явно выраженные делятся на слитные и раздельные.', 'الضَّمِيرُ لَفْظٌ يَكْنِي عَنِ الْمُتَكَلِّمِ أَوِ الْمُخَاطَبِ أَوِ الْغَائِبِ نِيَابَةً عَنِ الِاسْمِ، وَفَائِدَتُهُ الِاخْتِصَارُ. وَالضَّمَائِرُ بَارِزَةٌ وَمُسْتَتِرَةٌ، وَالضَّمَائِرُ الْبَارِزَةُ مُتَّصِلَةٌ وَمُنْفَصِلَةٌ.'),
    (2, 'الضَّمَائِرُ الْمُتَّصِلَةُ (слитные местоимения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-subject" dir="rtl" lang="ar">الضَّمِيرُ الْمُتَّصِلُ لَا يُبْدَأُ بِهِ فِي النُّطْقِ، وَلَا يَقَعُ بَعْدَ إِلَّا. وَيَكُونُ فِي مَحَلِّ رَفْعٍ، أَوْ نَصْبٍ، أَوْ جَرٍّ بِحَسَبِ مَوْقِعِهِ الْإِعْرَابِيِّ.</span><p class="rule-study-text">Слитное местоимение не начинает высказывание и не употребляется после إِلَّا. По синтаксической позиции оно бывает местоимением именительного, винительного или родительного разряда.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Определяющий пример</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">رَأَيْتُهُ.</span><span class="rule-example-ru">Я увидел его: تَاءٌ обозначает говорящего, а هَاءٌ — объект третьего лица.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Местоимения именительного разряда</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الضَّمِيرُ</span><span class="rule-table-ru">местоимение</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">التَّاءُ الْمُتَحَرِّكَةُ</span><span class="rule-table-ru">огласованная ت</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ذَهَبْتَ، ذَهَبْتِ، ذَهَبْتُ</span><span class="rule-table-ru">ты (м.) ушёл; ты (ж.) ушла; я ушёл</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ضَمِيرُ رَفْعٍ</span><span class="rule-table-ru">слитное местоимение именительного разряда</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">وَاوُ الْجَمَاعَةِ</span><span class="rule-table-ru">وَاوٌ мужского множественного числа</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ذَهَبُوا، يَذْهَبُونَ، اِذْهَبُوا</span><span class="rule-table-ru">они ушли; они уходят; уходите</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">لِجَمْعِ الْمُذَكَّرِ</span><span class="rule-table-ru">для мужского множественного числа</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَلِفُ الِاثْنَيْنِ</span><span class="rule-table-ru">алиф двойственного числа</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ذَهَبَا، يَذْهَبَانِ، اِذْهَبَا</span><span class="rule-table-ru">они двое ушли; они двое уходят; уходите вдвоём</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">لِلْمُثَنَّى</span><span class="rule-table-ru">для двойственного числа</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">يَاءُ الْمُخَاطَبَةِ</span><span class="rule-table-ru">يَاءٌ обращения к женщине</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَذْهَبِينَ، اِذْهَبِي</span><span class="rule-table-ru">ты (ж.) уходишь; уходи</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">لِلْمُخَاطَبَةِ</span><span class="rule-table-ru">для собеседницы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">نُونُ النِّسْوَةِ</span><span class="rule-table-ru">نُونٌ женского множественного числа</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ذَهَبْنَ، يَذْهَبْنَ، اِذْهَبْنَ</span><span class="rule-table-ru">они (ж.) ушли; они уходят; уходите</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">لِجَمْعِ الْمُؤَنَّثِ</span><span class="rule-table-ru">для женского множественного числа</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">نَا الْمُتَكَلِّمِينَ</span><span class="rule-table-ru">نَا говорящих</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ذَهَبْنَا</span><span class="rule-table-ru">мы ушли</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">لِلْمُتَكَلِّمِينَ</span><span class="rule-table-ru">для говорящих</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Местоимения винительного разряда</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الضَّمِيرُ</span><span class="rule-table-ru">местоимение</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">يَاءُ الْمُتَكَلِّمِ</span><span class="rule-table-ru">يَاءٌ говорящего</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سَأَلَنِي، يَسْأَلُنِي، اِسْأَلْنِي</span><span class="rule-table-ru">спросил меня; спрашивает меня; спроси меня</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">إِيَّايَ</span><span class="rule-table-ru">меня</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">كَافُ الْمُخَاطَبِ</span><span class="rule-table-ru">كَافٌ собеседника</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سَأَلَكَ، يَسْأَلُكَ</span><span class="rule-table-ru">спросил тебя; спрашивает тебя</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">إِيَّاكَ</span><span class="rule-table-ru">тебя</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">هَاءُ الْغَائِبِ</span><span class="rule-table-ru">هَاءٌ третьего лица</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سَأَلَهُ، يَسْأَلُهُ، اِسْأَلْهُ</span><span class="rule-table-ru">спросил его; спрашивает его; спроси его</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">إِيَّاهُ</span><span class="rule-table-ru">его</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">نَا الْمُتَكَلِّمِينَ</span><span class="rule-table-ru">نَا говорящих</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سَأَلَنَا، يَسْأَلُنَا، اِسْأَلْنَا</span><span class="rule-table-ru">спросил нас; спрашивает нас; спроси нас</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">إِيَّانَا</span><span class="rule-table-ru">нас</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Местоимения родительного разряда</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الضَّمِيرُ</span><span class="rule-table-ru">местоимение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَعَ الِاسْمِ وَحَرْفِ الْجَرِّ</span><span class="rule-table-ru">с именем и предлогом</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">يَاءُ الْمُتَكَلِّمِ</span><span class="rule-table-ru">يَاءٌ говорящего</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كِتَابِي، لِي</span><span class="rule-table-ru">моя книга; мне / у меня</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">لِلْمُتَكَلِّمِ</span><span class="rule-table-ru">для говорящего</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">كَافُ الْمُخَاطَبِ</span><span class="rule-table-ru">كَافٌ собеседника</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كِتَابُكَ، لَكَ</span><span class="rule-table-ru">твоя книга; тебе / у тебя</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">لِلْمُخَاطَبِ</span><span class="rule-table-ru">для собеседника</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">هَاءُ الْغَائِبِ</span><span class="rule-table-ru">هَاءٌ третьего лица</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كِتَابُهُ، لَهُ</span><span class="rule-table-ru">его книга; ему / у него</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">لِلْغَائِبِ</span><span class="rule-table-ru">для третьего лица</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">نَا الْمُتَكَلِّمِينَ</span><span class="rule-table-ru">نَا говорящих</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كِتَابُنَا، لَنَا</span><span class="rule-table-ru">наша книга; нам / у нас</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">لِلْمُتَكَلِّمِينَ</span><span class="rule-table-ru">для говорящих</span></td></tr></tbody></table></div></div></div>', 'Слитное местоимение не начинает высказывание и не употребляется после إِلَّا. По синтаксической позиции оно бывает местоимением именительного, винительного или родительного разряда.', 'الضَّمِيرُ الْمُتَّصِلُ لَا يُبْدَأُ بِهِ فِي النُّطْقِ، وَلَا يَقَعُ بَعْدَ إِلَّا. وَيَكُونُ فِي مَحَلِّ رَفْعٍ، أَوْ نَصْبٍ، أَوْ جَرٍّ بِحَسَبِ مَوْقِعِهِ الْإِعْرَابِيِّ.'),
    (3, 'الضَّمَائِرُ الْمُنْفَصِلَةُ (раздельные местоимения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-subject" dir="rtl" lang="ar">الضَّمِيرُ الْمُنْفَصِلُ يُبْدَأُ بِهِ فِي النُّطْقِ، وَيَقَعُ بَعْدَ إِلَّا. وَهُوَ إِمَّا ضَمِيرُ رَفْعٍ وَإِمَّا ضَمِيرُ نَصْبٍ؛ أَمَّا ضَمَائِرُ الْجَرِّ فَلَا تَأْتِي إِلَّا مُتَّصِلَةً.</span><p class="rule-study-text">Раздельное местоимение может начинать высказывание и употребляться после إِلَّا. Раздельные формы бывают именительного и винительного разряда; местоимения родительного разряда бывают только слитными.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры определения</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">أَنَا مُجْتَهِدٌ، وَأَنْتَ كَسْلَانُ.</span><span class="rule-example-ru">Я старательный, а ты ленивый.</span></div><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">مَا رَأَيْتُ إِلَّا إِيَّاكَ.</span><span class="rule-example-ru">Я не видел никого, кроме тебя.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Раздельные местоимения именительного разряда</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الرُّتْبَةُ</span><span class="rule-table-ru">лицо</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الضَّمَائِرُ</span><span class="rule-table-ru">формы</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُتَكَلِّمُ</span><span class="rule-table-ru">говорящий</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَنَا، نَحْنُ</span><span class="rule-table-ru">я; мы</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ضَمَائِرُ رَفْعٍ</span><span class="rule-table-ru">местоимения именительного разряда</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُخَاطَبُ</span><span class="rule-table-ru">собеседник</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَنْتَ، أَنْتِ، أَنْتُمَا، أَنْتُمْ، أَنْتُنَّ</span><span class="rule-table-ru">ты (м.); ты (ж.); вы двое; вы (м.); вы (ж.)</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ضَمَائِرُ رَفْعٍ</span><span class="rule-table-ru">местоимения именительного разряда</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْغَائِبُ</span><span class="rule-table-ru">третье лицо</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">هُوَ، هِيَ، هُمَا، هُمْ، هُنَّ</span><span class="rule-table-ru">он; она; они двое; они (м.); они (ж.)</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ضَمَائِرُ رَفْعٍ</span><span class="rule-table-ru">местоимения именительного разряда</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Раздельные местоимения винительного разряда</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الرُّتْبَةُ</span><span class="rule-table-ru">лицо</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الضَّمَائِرُ</span><span class="rule-table-ru">формы</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُتَكَلِّمُ</span><span class="rule-table-ru">говорящий</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">إِيَّايَ، إِيَّانَا</span><span class="rule-table-ru">меня; нас</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">ضَمَائِرُ نَصْبٍ</span><span class="rule-table-ru">местоимения винительного разряда</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُخَاطَبُ</span><span class="rule-table-ru">собеседник</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">إِيَّاكَ، إِيَّاكِ، إِيَّاكُمَا، إِيَّاكُمْ، إِيَّاكُنَّ</span><span class="rule-table-ru">тебя (м.); тебя (ж.); вас двоих; вас (м.); вас (ж.)</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">ضَمَائِرُ نَصْبٍ</span><span class="rule-table-ru">местоимения винительного разряда</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْغَائِبُ</span><span class="rule-table-ru">третье лицо</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">إِيَّاهُ، إِيَّاهَا، إِيَّاهُمَا، إِيَّاهُمْ، إِيَّاهُنَّ</span><span class="rule-table-ru">его; её; их двоих; их (м.); их (ж.)</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">ضَمَائِرُ نَصْبٍ</span><span class="rule-table-ru">местоимения винительного разряда</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Важное ограничение</span><div class="rule-example-list"><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">ضَمَائِرُ الْجَرِّ لَا تَأْتِي إِلَّا مُتَّصِلَةً.</span><span class="rule-example-ru">Местоимения родительного разряда употребляются только в слитной форме.</span></div></div></div></div>', 'Раздельное местоимение может начинать высказывание и употребляться после إِلَّا. Раздельные формы бывают именительного и винительного разряда; местоимения родительного разряда бывают только слитными.', 'الضَّمِيرُ الْمُنْفَصِلُ يُبْدَأُ بِهِ فِي النُّطْقِ، وَيَقَعُ بَعْدَ إِلَّا. وَهُوَ إِمَّا ضَمِيرُ رَفْعٍ وَإِمَّا ضَمِيرُ نَصْبٍ؛ أَمَّا ضَمَائِرُ الْجَرِّ فَلَا تَأْتِي إِلَّا مُتَّصِلَةً.'),
    (4, 'رُتَبُ الضَّمَائِرِ (порядок лиц местоимений)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-subject" dir="rtl" lang="ar">لِلضَّمَائِرِ ثَلَاثُ رُتَبٍ مُرَتَّبَةٌ هَكَذَا: الْمُتَكَلِّمُ، ثُمَّ الْمُخَاطَبُ، ثُمَّ الْغَائِبُ.</span><p class="rule-study-text">У местоимений три разряда по лицу в следующем порядке: говорящий, затем собеседник, затем третье лицо.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Три разряда</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الرُّتْبَةُ</span><span class="rule-table-ru">порядковое место</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">نَوْعُ الضَّمِيرِ</span><span class="rule-table-ru">тип местоимения</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأُولَى</span><span class="rule-table-ru">первая</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُتَكَلِّمُ</span><span class="rule-table-ru">говорящий</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَنْ يَتَكَلَّمُ</span><span class="rule-table-ru">тот, кто говорит</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الثَّانِيَةُ</span><span class="rule-table-ru">вторая</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُخَاطَبُ</span><span class="rule-table-ru">собеседник</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَنْ يُوَجَّهُ إِلَيْهِ الْكَلَامُ</span><span class="rule-table-ru">тот, к кому обращаются</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الثَّالِثَةُ</span><span class="rule-table-ru">третья</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْغَائِبُ</span><span class="rule-table-ru">третье лицо</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَنْ يُتَحَدَّثُ عَنْهُ</span><span class="rule-table-ru">тот, о ком говорят</span></td></tr></tbody></table></div></div></div>', 'У местоимений три разряда по лицу в следующем порядке: говорящий, затем собеседник, затем третье лицо.', 'لِلضَّمَائِرِ ثَلَاثُ رُتَبٍ مُرَتَّبَةٌ هَكَذَا: الْمُتَكَلِّمُ، ثُمَّ الْمُخَاطَبُ، ثُمَّ الْغَائِبُ.'),
    (5, 'مَوَاضِعُ ضَمِيرِ النَّصْبِ الْمُنْفَصِلِ (случаи употребления раздельного местоимения винительного разряда)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-object" dir="rtl" lang="ar">يَجِبُ اسْتِعْمَالُ ضَمِيرِ النَّصْبِ الْمُنْفَصِلِ إِذَا تَقَدَّمَ الْمَفْعُولُ بِهِ عَلَى عَامِلِهِ، أَوْ وَقَعَ الضَّمِيرُ بَعْدَ حَرْفِ عَطْفٍ، أَوْ بَعْدَ إِلَّا، أَوْ بَعْدَ ضَمِيرِ نَصْبٍ مُتَّصِلٍ، أَوْ كَانَ مَفْعُولًا لِمَصْدَرٍ أُضِيفَ إِلَى فَاعِلِهِ.</span><p class="rule-study-text">Шарх перечисляет пять случаев обязательной раздельной формы местоимения винительного разряда: перед своим управляющим словом, после союза, после إِلَّا, после слитного объектного местоимения и при масдаре, присоединённом к своему субъекту.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Пять обязательных случаев</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَوْضِعُ</span><span class="rule-table-ru">условие</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">перевод и пояснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">تَقَدُّمُ الْمَفْعُولِ بِهِ عَلَى عَامِلِهِ</span><span class="rule-table-ru">объект стоит перед управляющим словом</span></td><td><span class="rule-table-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿إِيَّاكَ نَعۡبُدُ﴾</span><span class="rule-table-ru">Тебе одному мы поклоняемся.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">إِيَّاكَ مَفْعُولٌ بِهِ مُقَدَّمٌ</span><span class="rule-table-ru">إِيَّاكَ — вынесенное вперёд прямое дополнение</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">تَقَدُّمُ الْمَفْعُولِ بِهِ عَلَى عَامِلِهِ</span><span class="rule-table-ru">объект стоит перед управляющим словом</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أَإِيَّايَ تَسْأَلُ؟</span><span class="rule-table-ru">Неужели меня ты спрашиваешь?</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">إِيَّايَ قَبْلَ الْفِعْلِ</span><span class="rule-table-ru">إِيَّايَ стоит перед глаголом</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">بَعْدَ حَرْفِ الْعَطْفِ</span><span class="rule-table-ru">после сочинительного союза</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">رَأَيْتُكَ وَإِيَّاهُ.</span><span class="rule-table-ru">Я увидел тебя и его.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">وَاوُ الْعَطْفِ</span><span class="rule-table-ru">местоимение следует после وَاو союза</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">بَعْدَ إِلَّا</span><span class="rule-table-ru">после إِلَّا</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَا رَأَيْتُ إِلَّا إِيَّاكَ.</span><span class="rule-table-ru">Я не видел никого, кроме тебя.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِلَّا</span><span class="rule-table-ru">частица исключения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">بَعْدَ ضَمِيرِ نَصْبٍ مُتَّصِلٍ</span><span class="rule-table-ru">после слитного объектного местоимения</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أَعْطَيْتُهُ إِيَّاهُ.</span><span class="rule-table-ru">Я дал это ему.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الضَّمِيرُ الثَّانِي مُنْفَصِلٌ</span><span class="rule-table-ru">второе местоимение употреблено раздельно</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَفْعُولٌ لِمَصْدَرٍ أُضِيفَ إِلَى فَاعِلِهِ</span><span class="rule-table-ru">объект масдара, присоединённого к своему субъекту</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">زِيَارَةُ الْمُدِيرِ إِيَّانَا غَدًا إِنْ شَاءَ اللَّهُ.</span><span class="rule-table-ru">Посещение директором нас — завтра, если пожелает Аллах.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">إِيَّانَا مَفْعُولٌ بِهِ لِلْمَصْدَرِ</span><span class="rule-table-ru">إِيَّانَا — прямое дополнение при масдаре</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Разбор последнего примера</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">الْمُدِيرِ: مُضَافٌ إِلَيْهِ، وَهُوَ فَاعِلٌ فِي الْأَصْلِ.</span><span class="rule-example-ru">الْمُدِيرِ — مُضَافٌ إِلَيْهِ, а по исходному смыслу является субъектом действия.</span></div><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">إِيَّانَا: مَفْعُولٌ بِهِ، عَامِلُهُ الْمَصْدَرُ؛ لِأَنَّ الْمَصْدَرَ يَعْمَلُ عَمَلَ فِعْلِهِ.</span><span class="rule-example-ru">إِيَّانَا — прямое дополнение; им управляет масдар, поскольку масдар действует так же, как его глагол.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">يَزُورُنَا الْمُدِيرُ غَدًا إِنْ شَاءَ اللَّهُ.</span><span class="rule-example-ru">Исходная глагольная конструкция: «Директор посетит нас завтра, если пожелает Аллах».</span></div></div></div></div>', 'Шарх перечисляет пять случаев обязательной раздельной формы местоимения винительного разряда: перед своим управляющим словом, после союза, после إِلَّا, после слитного объектного местоимения и при масдаре, присоединённом к своему субъекту.', 'يَجِبُ اسْتِعْمَالُ ضَمِيرِ النَّصْبِ الْمُنْفَصِلِ إِذَا تَقَدَّمَ الْمَفْعُولُ بِهِ عَلَى عَامِلِهِ، أَوْ وَقَعَ الضَّمِيرُ بَعْدَ حَرْفِ عَطْفٍ، أَوْ بَعْدَ إِلَّا، أَوْ بَعْدَ ضَمِيرِ نَصْبٍ مُتَّصِلٍ، أَوْ كَانَ مَفْعُولًا لِمَصْدَرٍ أُضِيفَ إِلَى فَاعِلِهِ.'),
    (6, 'حُكْمُ الْوَصْلِ وَالْفَصْلِ بَيْنَ ضَمِيرَيْ نَصْبٍ (слитное и раздельное употребление двух объектных местоимений)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-object" dir="rtl" lang="ar">إِذَا اجْتَمَعَ ضَمِيرَانِ لِلنَّصْبِ مِنْ رُتْبَةٍ وَاحِدَةٍ، وَجَبَ الْفَصْلُ بَيْنَهُمَا؛ وَإِذَا اخْتَلَفَتْ رُتْبَتُهُمَا، جَازَ الْفَصْلُ وَالْوَصْلُ.</span><p class="rule-study-text">Если два объектных местоимения относятся к одному разряду лица, их обязательно разделяют. Если их разряды различны, допустимы и раздельная, и слитная формы.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Сопоставление двух случаев</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَالُ الضَّمِيرَيْنِ</span><span class="rule-table-ru">отношение разрядов</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْحُكْمُ</span><span class="rule-table-ru">правило</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مِنْ رُتْبَةٍ وَاحِدَةٍ</span><span class="rule-table-ru">оба местоимения одного разряда</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">وُجُوبُ الْفَصْلِ</span><span class="rule-table-ru">раздельная форма обязательна</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أَعْطَيْتُهُ إِيَّاهُ.</span><span class="rule-table-ru">Я дал это ему: оба местоимения относятся к третьему лицу.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مِنْ رُتْبَتَيْنِ مُخْتَلِفَتَيْنِ</span><span class="rule-table-ru">местоимения разных разрядов</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">جَوَازُ الْفَصْلِ وَالْوَصْلِ</span><span class="rule-table-ru">разрешены обе формы</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أَعْطَيْتُكَ إِيَّاهُ.</span><span class="rule-table-ru">Я дал это тебе — раздельная форма.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مِنْ رُتْبَتَيْنِ مُخْتَلِفَتَيْنِ</span><span class="rule-table-ru">собеседник и третье лицо</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">جَوَازُ الْوَصْلِ</span><span class="rule-table-ru">допустима слитная форма</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أَعْطَيْتُكَهُ.</span><span class="rule-table-ru">Я дал это тебе — слитная форма.</span></td></tr></tbody></table></div></div></div>', 'Если два объектных местоимения относятся к одному разряду лица, их обязательно разделяют. Если их разряды различны, допустимы и раздельная, и слитная формы.', 'إِذَا اجْتَمَعَ ضَمِيرَانِ لِلنَّصْبِ مِنْ رُتْبَةٍ وَاحِدَةٍ، وَجَبَ الْفَصْلُ بَيْنَهُمَا؛ وَإِذَا اخْتَلَفَتْ رُتْبَتُهُمَا، جَازَ الْفَصْلُ وَالْوَصْلُ.')
)
update public.rules as r
set title = incoming.title,
    content = incoming.content,
    rule_kind = 'rule',
    summary = incoming.summary,
    rule_ar = incoming.rule_ar
from incoming
where r.course_name = 'Мединский курс (Том 4)'
  and r.lesson_number = '10'
  and r.sort_order = incoming.sort_order;

delete from public.rule_sources
where rule_id in (
  select id from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '10'
);

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الدَّرْسُ الْعَاشِرُ
الضَّمَائِرُ
الضَّمائرُ: ألفاظ موضوعة للكناية عن المتكلم، أو المخاطب، أو الغائب، نيابة عن الأسماء .
فائدتها : الاختصار .
أنواعها : تنقسم الضمائر إلى قسمين :
أ- ضمائرُ بَارِزَةٌ .                  ب- ضمائرُ مُسْتَتِرَةٌ
تنقسم الضمائر البَارِزَةُ إلى قسمين :
أ- ضمائرُ مُتَّصِلَةٌ                   ب- ضمائرُ مُنْفَصِلَةٌ .', 42, 42, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '10' and sort_order = 1;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'أَوَّلاً : الضَّمَائِرُ الْمُتَّصِلَةُ
الضمائرُ المتَّصلة ، هي : التي لا يُبْدَأُ بها في النطق , ولا تَقَعُ بعد ( إلاَّ )
كالتاء ، والهاء في قولك : رأيتُهُ .
تنقسم الضمائر المتصلة باعتبار موقعها الإعرابي إلى ثلاثة أقسام ، هي :
أ- ضمائرُ رفعٍ , وهي :
1- التاء المتحركة , نحو : ذَهَبْتَُِ .
2- واو الجماعة , نحو : ذَهَبُوا ، يَذْهَبُونَ ، اذْهَبُوا .
3- ألف الاثنين , نحو : ذَهَبَا ، يَذْهَبَانِ ، اذْهَبَا .
4- ياء المخاطبة , نحو : تَذْهَبِينَ ، اذْهَبِي .
5- نون النسوة , نحو : ذَهَبْنَ ، يَذْهَبْنَ ، اذْهَبْنَ .
6- نا الْمُتَكَلِّمِين , نحو : ذَهَبْنَا .
ب- ضمائرُ نصبٍ , وهي :
1- ياء المتكلّم , نحو : سَأَلَنِي ، يَسْأَلُنِي ، اسْأَلْنِي .
2- كاف المخاطَب , نحو : سَألَكَ ، يَسْأَلُكَ .
3- هاء الغائب , نحو : سَأَلَهُ، يَسْأَلُهُ ، اسْأَلْهُ .
4- نا الْمُتَكَلَّمِين , نحو : سَأَلَنَا ، يَسْأَلُنَا ، اسْأَلْنَا .
ج- ضمائرُ جرٍّ , وهي :
1- ياء المتكلّم , نحو : كتابي ، لي .
2- كاف المخاطَب , نحو : كتابك ، لك .
3- هاء الغائب , نحو : كتابه ، له .
4- نا الْمُتَكَلَّمِين , نحو : كتابنا ، لنا .', 42, 43, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '10' and sort_order = 2;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'ثَانِياً : الضَّمَائِرُ الْمُنْفَصِلَةُ
هي : التي يُبْدَأُ بها في النُّطْقِ ، وتَقَعُ بعد ( إلاَّ ) . الضمائرُ المنفصلةُ ،
نحو : أنا مجتهد وأنت كسلان ، ونحو : ما رأيتُ إلا إِيَّاكَ .
تنقسم الضمائر المنفصلة باعتبار موقعها الإعرابي إلى قسمين هما :
أ- ضمائرُ رفعٍ , وهي :
1- المتكلَّم : أنا ،  ونحن .
2- المخاطَب : أَنْتَِ ، وأَنْتُمَا ، وأَنْتُمْ ،وأَنْتُنَّ .
3- الغائب : هُوَ ، وهِيَ ، وهُمَا ، وهُمْ ، وهُنَّ .
ب- ضمائرُ نصبٍ , وهي :
1- المتكلَّم : إِيَّايَ ، إِيَّانَا .
2- المخاطَب : إِيَّاكَِ ،  إِيَّاكُمَا ، إِيَّاكُمْ ، إِيَّاكُنَّ .
3- الغائب : إِيَّاهُ ، إِيَّاهَا ، إِيَّاهُمَا ، إِيَّاهُمْ ، إِيَّاهُنَّ .
ضمائرُ الجرِّ لا تأتي إلاَّ مُتَّصِلَةً .', 43, 44, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '10' and sort_order = 3;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'رُتَبُ الضَّمَائِرِ
للضّمائرِ ثلاثُ رُتَبٍ ، هي :
1- الْمُتَكَلِّمُ            2- الْمُخَاطَبُ              3- الْغَائِبُ .', 44, 44, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '10' and sort_order = 4;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'مواضعُ الإتيانِ بضميرِ النَّصبِ المنفصلِ :
يجب استعمال ضمير النصب المنفصل في المواضع الآتية :
1- إذا تقدم المفعول به على عامله , نحو قوله تعالى : ﴿ إِيَّاكَ نَعْبُدُ ﴾ ونحو قولك :
أَإيَّايَ تَسْأَلُ ؟ .
2- إذا وقع الضمير بعد حرف العطف , نحو : رَأَيْتُكَ وإِيَّاهُ .
3- إذا وقع الضمير بعد ( إلاّ ) نحو : ما رأيتُ إلاَّ إِيَّاكَ .
4- إذا وقع الضمير بعد ضمير نصب متصل , نحو : أَعْطَيْتُهُ إِيَّاهُ .
5- إذا وقع الضمير مفعولا لمصدر أُضِيفَ إلى فاعله , نحو: زيارةُ المدِيرِ إِيَّانَا غداً إن شاء الله . فالمدير : مُضاف إليه ( وهو فاعل في الأصل ) وإِيَّانَا : مفعول به عامله المصدر ؛ لأنَّ المصدرَ يَعْمَلُ عَمَلَ فِعْلِهِ ؛ إذ أصل الجملة : يَزُورُنَا المديرُ غداً إن شاء الله .', 44, 44, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '10' and sort_order = 5;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'حُكْمُ الْوَصْلِ ، وَالْفَصْلِ :
إذا اجتمع ضميران للنصب ، وكان الضميران من رتبة واحدة , وجب الفصل بينهما ,  نحو : أَعْطَيْتُهُ إِيَّاهُ ، يجب الفصل هنا ؛ لأن الضميرين من رُتبة واحدة ، هي رتبة الغائب .
أما إذا كان الضميران من رتبة مختلفة فيجوز الفصل والوصل ، نحو : أَعْطَيْتُكَ إِيَّاهُ        ( بِالْفَصْل ) ويجوز : أَعْطَيْتُكَهُ ( بِالْوَصْلِ ) لأن الضميرين من رتبة مختلفة ، فالأول للمخاطَب ، والثاني للغائب .', 44, 44, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '10' and sort_order = 6;

do $migration$
declare
  updated_count integer;
  source_count integer;
begin
  select count(*) into updated_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '10' and rule_ar is not null and btrim(rule_ar) <> '';
  select count(*) into source_count
  from public.rule_sources rs
  join public.rules r on r.id = rs.rule_id
  where r.course_name = 'Мединский курс (Том 4)' and r.lesson_number = '10';
  if updated_count <> 6 or source_count <> 6 then
    raise exception 'Book 4 lesson 10 QA failed: rules %, sources %', updated_count, source_count;
  end if;
end $migration$;

commit;
